use crate::TaxYear;

#[derive(Debug)]
pub(crate) struct Parameter {
    pub value_eur: i128,
}

#[derive(Debug)]
pub(crate) struct Parameters {
    pub basic_allowance: Parameter,
}

// Generated by build.rs from rules/<year>/parameters.toml.
include!(concat!(env!("OUT_DIR"), "/parameters.rs"));

pub(crate) fn for_year(year: TaxYear) -> &'static Parameters {
    match year {
        TaxYear::Y2026 => &PARAMETERS_2026,
    }
}
